from fractions import Fraction
from collections import deque
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def check_reachability_shallow(m, n, max_depth=3):
    # Initial numbers
    x0 = Fraction(m, n)
    y0 = Fraction(n, m)

    if x0 == 1 or y0 == 1:
        return True

    # BFS implementation
    # Queue stores tuples: (set_of_numbers, current_depth)
    initial_set = frozenset({x0, y0})
    queue = deque([(initial_set, 0)])
    visited = {initial_set}

    while queue:
        current_set, depth = queue.popleft()

        if depth >= max_depth:
            continue

        elements = list(current_set)
        L = len(elements)

        # Iterate over all distinct pairs (x, y) in the current set
        for i in range(L):
            for j in range(i + 1, L):
                x = elements[i]
                y = elements[j]

                # 1. Arithmetic Mean (AM): (x+y)/2
                am = (x + y) / 2

                # 2. Harmonic Mean (HM): 2xy / (x+y)
                hm = (2 * x * y) / (x + y)

                new_numbers = [am, hm]

                for new_num in new_numbers:
                    if new_num == 1:
                        return True

                    new_set = current_set.union({new_num})
                    new_frozenset = frozenset(new_set)

                    if new_frozenset not in visited:
                        visited.add(new_frozenset)
                        queue.append((new_frozenset, depth + 1))

    return False

# 1. Generate all coprime pairs (m, n) such that m+n < 30 and m <= n
pairs = []
for m in range(1, 30):
    for n in range(m, 30):
        if m + n < 30 and gcd(m, n) == 1:
            if m != n:
                pairs.append((m, n))

# 2. Test only the very smallest pairs due to time constraints
# We will test pairs where m+n < 10
test_pairs = [(m, n) for m, n in pairs if m + n < 10]

print(f"Testing {len(test_pairs)} pairs with max depth 3.")

results = {}
for m, n in test_pairs:
    is_reachable = check_reachability_shallow(m, n)
    results[(m, n)] = is_reachable

# 3. Format output for notes.md
output = []
for (m, n), reachable in results.items():
    output.append(f"Pair ({m}, {n}): Reachable = {reachable}")

print("\\n---RESULTS---\\n" + "\\n".join(output))

